use vstd::prelude::*;

verus! {

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        // Same length as input
        rev.len() == s.len(),

        // Reversal property: for all valid indices k, rev[k] == s[n-1-k]
        forall|k: int|
            0 <= k < s.len() ==>
                rev[k] == s[s.len() - 1 - k],
{
    let n = s.len();
    let mut rev: Vec<i8> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == s.len(),
            i <= n,
            rev.len() == i,
            forall|k: int|
                0 <= k < i as int ==>
                    rev[k] == s[n - 1 - k],
    {
        // push s[n-1-i] into rev
        let idx = n - 1 - i;
        let v = s[idx];
        rev.push(v);
        i += 1;
    }

    rev
}

} // verus!